package cl.acis.catalogos.model; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="fotos_evidencia") public class FotoEvidencia { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false) Long ordenId; @Column(nullable=false) String nombreArchivo,rutaArchivo; @Enumerated(EnumType.STRING) @Column(nullable=false) TipoFoto tipo; Double latitud,longitud; @Column(nullable=false) Long subidaPorId; @Column(nullable=false) LocalDateTime creadaEn; public FotoEvidencia(){} @PrePersist void crear(){creadaEn=LocalDateTime.now();} public Long getId(){return id;} public Long getOrdenId(){return ordenId;} public void setOrdenId(Long v){ordenId=v;} public String getNombreArchivo(){return nombreArchivo;} public void setNombreArchivo(String v){nombreArchivo=v;} public String getRutaArchivo(){return rutaArchivo;} public void setRutaArchivo(String v){rutaArchivo=v;} public TipoFoto getTipo(){return tipo;} public void setTipo(TipoFoto v){tipo=v;} public Double getLatitud(){return latitud;} public void setLatitud(Double v){latitud=v;} public void setLatitud(double v){latitud=v;} public Double getLongitud(){return longitud;} public void setLongitud(Double v){longitud=v;} public void setLongitud(double v){longitud=v;} public Long getSubidaPorId(){return subidaPorId;} public void setSubidaPorId(Long v){subidaPorId=v;} public LocalDateTime getCreadaEn(){return creadaEn;} }
